mapper.select:
select c.*, IFNULL(e.name, '') as master_name, case when now() > c.end_date then '已结课' when now() < c.begin_date then '未开班' else '在读中' end as status from clazz c left join emp e on c.master_id = e.id
c.name like concat('%', #{name}, '%')
and c.begin_date >= #{beginDate}
and c.begin_date <= #{endDate}
order by c.update_time
